'use client';
import{useEffect,useRef,useState,type ReactNode}from'react';
import {AnimatePresence,motion,useReducedMotion} from 'motion/react';
import './block-member-list1.css';
export interface DirectoryTeam {id:string;code:string;name:string;color?:string}
export interface DirectoryMember {id:string;name:string;email:string;avatarUrl?:string;availability:'Available'|'Away'|'Offline';role:string;teams:DirectoryTeam[];joined:string;joinedAt?:string}
export type MemberSort='name-asc'|'name-desc'|'joined-asc'|'joined-desc'|'teams-asc'|'teams-desc';
export interface MemberDirectoryFilters {availability:string[];roles:string[];sort:MemberSort}
export interface BlockMemberList1Props {members:DirectoryMember[];title?:string;onFiltersChange?:(filters:MemberDirectoryFilters)=>void;onInvite:()=>void;onDisplay:()=>void;onMemberSelect?:(id:string)=>void;className?:string}
function Mark({type}:{type:string}){let shape:ReactNode;switch(type){case'filter':shape=<path d="M3 6h18M6 12h12M10 18h4"/>;break;case'display':shape=<><path d="M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6"/></>;break;case'plus':shape=<path d="M12 5v14M5 12h14"/>;break;case'back':shape=<path d="m15 6-6 6 6 6"/>;break;case'next':shape=<path d="m9 6 6 6-6 6"/>;break;case'check':shape=<path d="m5 12 4 4L19 6"/>;break;case'close':shape=<path d="m6 6 12 12M6 18 18 6"/>;break;case'team':shape=<><rect x="4" y="4" width="16" height="18" rx="2"/><path d="M8 2v4M16 2v4M7 19a5 5 0 0 1 10 0"/><circle cx="12" cy="11" r="3"/></>;break;case'Available':shape=<><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></>;break;case'Away':shape=<><circle cx="12" cy="12" r="9"/><path d="M12 7v5h4"/></>;break;case'Offline':shape=<circle cx="12" cy="12" r="9" strokeDasharray="3 4"/>;break;case'role':shape=<><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></>;break;default:shape=<path d="M8 4v16m-4-4 4 4 4-4M16 20V4m-4 4 4-4 4 4"/>}
 return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{shape}</svg>}
function TeamNames({teams}:{teams:DirectoryTeam[]}){const reduced=useReducedMotion();const[open,setOpen]=useState(false);const timer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);useEffect(()=>()=>clearTimeout(timer.current),[]);const show=()=>{clearTimeout(timer.current);timer.current=setTimeout(()=>setOpen(true),600)};const hide=()=>{clearTimeout(timer.current);setOpen(false)};return <span className="ml1-teams" onMouseEnter={show} onMouseLeave={hide}><button aria-label={`View ${teams.length} teams`} onFocus={()=>setOpen(true)} onBlur={hide} onClick={()=>setOpen(!open)} onKeyDown={e=>{if(e.key==='Escape'){e.stopPropagation();hide()}}}><Mark type="team"/>{teams.slice(0,2).map(t=>t.code).join(', ')}{teams.length>2&&` +${teams.length-2}`}</button><AnimatePresence>{open&&<motion.span initial={{opacity:0,y:-4,scale:.95,x:'-50%'}} animate={{opacity:1,y:0,scale:1,x:'-50%'}} exit={{opacity:0,y:-4,scale:.95,x:'-50%'}} transition={{duration:reduced?0:.15}} role="tooltip" className="ml1-tooltip">{teams.map(t=><span key={t.id} className="ml1-tooltip-team"><i style={{background:t.color||'#dbb57e'}}/><span><strong>{t.name}</strong><small>{t.code}</small></span></span>)}</motion.span>}</AnimatePresence></span>}
const initial:MemberDirectoryFilters={availability:[],roles:[],sort:'name-asc'};
export function BlockMemberList1({members,title='Members',onFiltersChange,onInvite,onDisplay,onMemberSelect,className=''}:BlockMemberList1Props){const reduced=useReducedMotion();const[filters,setFilters]=useState<MemberDirectoryFilters>(initial);const[open,setOpen]=useState(false);const[category,setCategory]=useState<'root'|'Availability'|'Role'|'Sort by'>('root');const filterRef=useRef<HTMLDivElement>(null);const trigger=useRef<HTMLButtonElement>(null);
 useEffect(()=>{if(!open)return;const dismiss=(e:PointerEvent)=>{if(!filterRef.current?.contains(e.target as Node))setOpen(false)};document.addEventListener('pointerdown',dismiss);return()=>document.removeEventListener('pointerdown',dismiss)},[open]);
 const update=(next:MemberDirectoryFilters)=>{setFilters(next);onFiltersChange?.(next)};const count=filters.availability.length+filters.roles.length+(filters.sort!=='name-asc'?1:0);
 const visible=members.filter(m=>(!filters.availability.length||filters.availability.includes(m.availability))&&(!filters.roles.length||filters.roles.includes(m.role))).slice().sort((a,b)=>{const direction=filters.sort.endsWith('desc')?-1:1;return direction*(filters.sort.startsWith('joined')?Date.parse(a.joinedAt||a.joined)-Date.parse(b.joinedAt||b.joined):filters.sort.startsWith('teams')?a.teams.length-b.teams.length:a.name.localeCompare(b.name))});
 const toggleValue=(key:'availability'|'roles',value:string)=>update({...filters,[key]:filters[key].includes(value)?filters[key].filter(v=>v!==value):[...filters[key],value]});
 function keyMenu(e:React.KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();setOpen(false);trigger.current?.focus()}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...filterRef.current!.querySelectorAll<HTMLButtonElement>('[role=option]')];const i=buttons.indexOf(document.activeElement as HTMLButtonElement);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}}
 const sortGroups=[{label:'Name',items:[['name-asc','A-Z'],['name-desc','Z-A']]},{label:'Joined',items:[['joined-asc','Oldest first'],['joined-desc','Newest first']]},{label:'Teams',items:[['teams-asc','Fewest first'],['teams-desc','Most first']]}];
 return <section className={`block-member-list1 ${className}`} data-capture-root><header className="ml1-header"><div className="ml1-heading">{title}<span>{members.length}</span></div><div className="ml1-actions"><div className="ml1-filter-anchor" ref={filterRef}><button ref={trigger} className="ml1-filter-trigger" aria-expanded={open} onClick={()=>setOpen(!open)}><Mark type="filter"/>Filter{count>0&&<small>{count}</small>}</button><AnimatePresence>{open&&<motion.div initial={{opacity:0,y:-8,scale:.95}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:-8,scale:.95}} transition={{duration:reduced?0:.1}} className="ml1-filter-menu" role="dialog" aria-label="Member filters" onKeyDown={keyMenu}>{category!=='root'&&<button className="ml1-filter-back" onClick={()=>setCategory('root')}><Mark type="back"/>{category}</button>}<div role="listbox" aria-label={category==='root'?'Filters':category} aria-multiselectable={category==='Availability'||category==='Role'}>{category==='root'?(['Availability','Role','Sort by'] as const).map((s,i)=><button role="option" aria-selected="false" autoFocus={i===0} key={s} onClick={()=>setCategory(s)}><Mark type={s==='Availability'?'Available':s==='Role'?'role':'sort'}/>{s}<Mark type="next"/></button>):category==='Availability'?['Available','Away','Offline'].map((s,i)=><button role="option" aria-selected={filters.availability.includes(s)} key={s} autoFocus={i===0} onClick={()=>toggleValue('availability',s)}><span className="ml1-status-icon" data-status={s}><Mark type={s}/></span>{s}{filters.availability.includes(s)&&<Mark type="check"/>}</button>):category==='Role'?['Guest','Member','Admin'].map((s,i)=><button role="option" aria-selected={filters.roles.includes(s)} key={s} autoFocus={i===0} onClick={()=>toggleValue('roles',s)}><Mark type="role"/>{s}{filters.roles.includes(s)&&<Mark type="check"/>}</button>):sortGroups.map(g=><div key={g.label}><p className="ml1-filter-label">{g.label}</p>{g.items.map(([value,label])=><button role="option" aria-selected={filters.sort===value} key={value} onClick={()=>update({...filters,sort:value as MemberSort})}>{label}{filters.sort===value&&<Mark type="check"/>}</button>)}</div>)}</div></motion.div>}</AnimatePresence></div><button onClick={onDisplay}><Mark type="display"/>Display</button>{count>0&&<button className="ml1-reset" onClick={()=>update(initial)}>Reset<Mark type="close"/></button>}<button className="ml1-invite" onClick={onInvite}><Mark type="plus"/>Invite Member</button></div></header><div className="ml1-scroll"><div className="ml1-columns"><span>Member</span><span>Availability</span><span>Role</span><span>Teams</span><span>Joined</span></div><div>{visible.map(member=><div className="ml1-row" key={member.id} data-member-id={member.id}><div className="ml1-person"><span className="ml1-avatar">{member.name[0]}{member.avatarUrl&&<img src={member.avatarUrl} alt={member.name}/>}<i data-status={member.availability}/></span><div>{onMemberSelect?<button className="ml1-name" onClick={()=>onMemberSelect(member.id)}>{member.name}</button>:<p className="ml1-name">{member.name}</p>}<p className="ml1-email">{member.email}</p></div></div><div className="ml1-availability"><span className="ml1-status-icon" data-status={member.availability}><Mark type={member.availability}/></span>{member.availability}</div><div className="ml1-role">{member.role}</div><TeamNames teams={member.teams}/><div className="ml1-joined">{member.joined}</div></div>)}</div>{!visible.length&&<p className="ml1-empty">No members match these filters.</p>}</div></section>;
}
export default BlockMemberList1;
